@startuml

class Sober {
}

class Car {
  + vehicleNumber: string
}

class Owner {
  + name: string
}

class Accident {
  + date: date
  + location: string
  + damageAmount: double
}

class RideHail {
  + pickUpTime: datetime
  + dropOffTime: datetime
  + pickUpLocation: string
  + dropOffLocation: string
  + rideDuration: string
  + distance: double
  + numberOfPassengers: int
  + fee: double
  + requestType: string
}

class RideShare {
  + pickUpTime: datetime
  + dropOffTime: datetime
  + pickUpLocation: string
  + dropOffLocation: string
  + rideDuration: string
  + distance: double
  + upfrontNegotiatedFee: double
}

class Customer {
  + name: string
}

abstract class TaxiService {
}

class RideHailService extends TaxiService {
}

class RideShareService extends TaxiService {
}

Sober "1" -- "*" Car : operates
Sober "1" -- "*" Owner : tracks
Car "1" -- "0..*" Accident : involved in
Car "1" -- "0..*" RideHail : provides
Car "1" -- "0..*" RideShare : provides
Owner "1" -- "0..*" Car : owns
RideHail "0..*" -- "1" Customer : lead customer
RideShare "0..*" -- "1..*" Customer : passengers

@enduml

